var COIN_IMG="data:image/png;base64,";

export default function CoinIcon({ size, ml, mr }) {
  var s = size || 14;
  return (
    <img
      src={COIN_IMG}
      style={{
        width: s,
        height: s,
        objectFit: "contain",
        verticalAlign: "middle",
        display: "inline-block",
        marginLeft: ml || 0,
        marginRight: mr || 0,
      }}
      alt="or"
    />
  );
}